/// Removes a prompt that has not been sent from the queue, and its file.
fn cancel(&mut self, id: usize, window: &mut Window, cx: &mut Context<Self>) {
    let Some(ix) = self.queue.iter().position(|item| item.id == id) else {
        return;
    };
